Definition unp_ok (m : word -> option byte) (E : env) (w : saddr * expr) : Prop :=
  unpoisoned m (estart E (fst w)) (estart E (fst w) + elenZ E (snd w)).

(* [comment removed for export] *)
Definition unp_racc (RNG : footprint) (E : env) (w : saddr * expr) : Prop :=
  rng RNG (ASHOFF + Z.shiftr (estart E (fst w)) 3) (Z.shiftr (elenZ E (snd w) + (estart E (fst w)) mod 8 + 7) 3).

Definition unp_cov (kn : list kentry) (uw : list (saddr * expr)) (X : expr) (n : nat) : bool :=
  existsb (fun w => zf_covers kn X 0 n (a_base (fst w)) (a_off (fst w)) (snd w)) uw.

(* [comment removed for export] *)
Definition unp_rd (kn : list kentry) (uw : list (saddr * expr)) (a : saddr) : bool :=
  Z.eqb (a_off a) ASHOFF &&
  match a_base a with
  | EAlu ALU_SRL X (ELit 3) => unp_cov kn uw X 1
  | _ => false
  end.

(* [comment removed for export] *)
Definition chk_rule (na : nat) (reads : list (saddr * nat * bool)) (kn : list kentry) (uw : list (saddr * expr))
    (s : sidecond) : bool :=
  match s with
  | SCBr true BC_LT L (EVar j) =>
      match L with
      | EAlu _ (EMd _ _ (EAlu _ (EAlu _ (EAlu _ B _) (ELit k)) _)) _ =>
          expr_eqb L (chk_ob (EVar j) B k) && Nat.leb na j && Z.leb 0 k && Z.leb k 7 &&
          match nth_error reads (j - na) with
          | Some (a, n, sx) =>
              Nat.eqb n 1 && sx && Z.eqb (a_off a) ASHOFF &&
              match a_base a with
              | EAlu ALU_SRL B' (ELit 3) => expr_eqb B' B && unp_cov kn uw B (Z.to_nat (k + 1))
              | _ => false
              end
          | None => false
          end
      | _ => false
      end
  | _ => false
  end.

(* [comment removed for export] *)
Definition rb_unp (na : nat) (reads : list (saddr * nat * bool)) (kn : list kentry) (uw : list (saddr * expr))
    (s : sidecond) : bool :=
  match s with
  | SCReadBase a n sx (EVar j) =>
      Nat.leb na j && Nat.eqb n 1 &&
      match nth_error reads (j - na) with
      | Some (a', n', sx') => saddr_eqb a a' && Nat.eqb n n' && Bool.eqb sx sx' && unp_rd kn uw a
      | None => false
      end
  | _ => false
  end.

Definition sc_auto3 (na : nat) (reads : list (saddr * nat * bool)) (kn : list kentry) (rr : list (saddr * expr))
    (ts : list zshz) (uw : list (saddr * expr)) (s : sidecond) : bool :=
  sc_auto2 na reads kn rr ts s || chk_rule na reads kn uw s || rb_unp na reads kn uw s.

Definition acc_auto3 (kn : list kentry) (ww : list (saddr * expr)) (ts : list zshz) (uw : list (saddr * expr))
    (an : saddr * nat) : bool :=
  acc_auto2 kn ww ts an || (Nat.eqb (snd an) 1 && unp_rd kn uw (fst an)).

Section UnpSound.
Variable segs : list Segment.

Lemma unp_cov_sound : forall m E M kn uw X n, know_ok segs E M kn -> Forall (unp_ok m E) uw -> (n <= 8)%nat ->
  unp_cov kn uw X n = true ->
  exists lo hi, unpoisoned m lo hi /\ lo <= bv_unsigned (edenot E X) /\ bv_unsigned (edenot E X) + Z.of_nat n <= hi.
Proof.
