Theorem chk_rule_sound : forall m ws reads kn uw s,
  let E := kx_env ws (kx_vals segs m ws reads) in
  reads_scoped (length ws) reads = true ->
  know_ok segs E m kn -> Forall (unp_ok m E) uw ->
  chk_rule (length ws) reads kn uw s = true -> sc_denot segs m E s.
