Theorem kx_scs_bulk3 : forall m ws reads kn rr ts uw scs,
  let E := kx_env ws (kx_vals segs m ws reads) in
  reads_scoped (length ws) reads = true ->
  know_ok segs E m kn -> Forall (region_ok segs m E) rr -> Forall (shz_ok m E) ts -> Forall (unp_ok m E) uw ->
  scs_denot segs m E (List.filter (fun s => negb (sc_auto3 (length ws) reads kn rr ts uw s)) scs) ->
  scs_denot segs m E scs.
Proof.
