Lemma kx_accs_ok_part3 : forall RNG E M m kn ww ts uw accs,
  know_ok segs E M kn -> Forall (win_ok RNG E) ww -> Forall (shz_racc RNG E) ts ->
  Forall (unp_ok m E) uw -> Forall (unp_racc RNG E) uw ->
  Forall (accP RNG E) (List.filter (fun an => negb (acc_auto3 kn ww ts uw an)) accs) ->
