Ltac kx_shr_arith :=
  cbv [zden nth]; unfold shad, shlen, ASHOFF in *; rewrite ?Z.shiftr_div_pow2 by lia; change (2^3) with 8;
  Z.div_mod_to_equations; lia.

(* [comment removed for export] *)
Ltac kx_unp1 zv xs m :=
  lazymatch goal with
  | |- unp_ok _ _ (zr_reg (?a, ?n)) =>
      let s1 := eval vm_compute in (zsa a) in
      lazymatch s1 with SA ?b ?c =>
        first [ match goal with H : unpoisoned m ?A ?B |- _ =>
                  apply (zu_ok zv xs m a n b c A B);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact H | cbv [zden nth]; lia | cbv [zden nth]; lia ] end
              | idtac ]
      end
  end.

(* [comment removed for export] *)
Ltac kx_unpr1 RNG zv xs :=
  lazymatch goal with
  | |- unp_racc _ _ (zr_reg (?a, ?n)) =>
      let s1 := eval vm_compute in (zsa a) in
      lazymatch s1 with SA ?b ?c =>
        first [ match goal with H : rng RNG (shad ?A) (shlen (?L + 7)) |- _ =>
                  apply (zur_ok_blk zv xs RNG a n b c A L);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact H | first [assumption | lia] | lia
                  | cbv [zden nth]; lia | cbv [zden nth]; lia ] end
              | match goal with H : rng RNG ?S ?L |- _ =>
                  apply (zur_ok zv xs RNG a n b c S L);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact H | kx_shr_arith | kx_shr_arith ] end
              | idtac ]
      end
  end.

