(* [comment removed for export] *)
Fixpoint c8_offsets (off : nat) (cs : list cell) : list nat :=
  match cs with
  | [] => []
  | C8 _ :: r => off :: c8_offsets (off + 8) r
  | c :: r => c8_offsets (off + csize c) r
  end.

Ltac kx_word_try segs zv xs m a v b c A cs H ks :=
  lazymatch ks with
  | nil => fail
  | cons ?k ?rest =>
      first [ eapply (zk_word_ok segs zv xs m a v b c A cs k _);
              [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
              | kx_arith | kx_arith | kx_arith | kx_arith | exact H | reflexivity
              | cbv [zden nth]; lia | cbv [zden nth]; f_equal; first [reflexivity | lia] ]
            | kx_word_try segs zv xs m a v b c A cs H rest ]
  end.

Ltac kx_word1 segs zv xs m :=
  lazymatch goal with
  | |- kentry_ok _ _ _ (zk_ent (ZKWord ?a 8 ?v)) =>
      let s1 := eval vm_compute in (zsa a) in
      lazymatch s1 with SA ?b ?c =>
        first [ match goal with H : rw_cells segs m ?A ?cs |- _ =>
                  let ks := eval vm_compute in (c8_offsets 0 cs) in
                  kx_word_try segs zv xs m a v b c A cs H ks end
              | idtac ]
      end
  end.

