Ltac kx_disj_apart :=
  cbv [zden nth];
  first [ match goal with H : apart ?A ?N ?B ?M |- _ =>
            first [ apply (apart_sub A N B M _ _ _ _ H); lia | apply (apart_sub' A N B M _ _ _ _ H); lia ] end
        | lia ].

Ltac kx_know1m segs zv xs m :=
  lazymatch goal with
  | |- kentry_ok _ _ _ (zk_ent (ZKWord _ 8 _)) => kx_word1 segs zv xs m
  | |- kentry_ok _ _ _ (zk_ent (ZKDisj ?a1 ?n1 ?a2 ?n2)) =>
      let s1 := eval vm_compute in (zsa a1) in let s2 := eval vm_compute in (zsa a2) in
      lazymatch s1 with SA ?b1 ?c1 => lazymatch s2 with SA ?b2 ?c2 =>
        apply (zk_disj_ok segs zv xs m a1 n1 a2 n2 b1 c1 b2 c2);
        [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
        | vm_compute; reflexivity | vm_compute; reflexivity
        | kx_arith | kx_arith | kx_arith | kx_arith | kx_arith | kx_arith | kx_disj_apart ]
      end end
  | |- kentry_ok _ _ _ (zk_ent (ZKWr ?a ?n)) =>
      (* [comment removed for export] *)
      let s1 := eval vm_compute in (zsa a) in
      lazymatch s1 with SA ?b ?c =>
        first [ match goal with H : wr_at segs m ?A ?N |- _ =>
                  apply (zk_wr_ok segs zv xs m a n b c A N);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact H | cbv [zden nth]; lia | cbv [zden nth]; lia ] end
              | match goal with H : u8arr segs m ?A ?bs |- _ =>
                  apply (zk_wr_ok segs zv xs m a n b c A (Z.of_nat (length bs)));
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact (proj2 H) | cbv [zden nth]; lia | cbv [zden nth]; lia ] end
              | match goal with H : rw_cells segs m ?A ?cs |- _ =>
                  apply (zk_wr_ok segs zv xs m a n b c A (Z.of_nat (cells_size cs)));
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact (proj2 H) | cbv [zden nth]; lia
                  | cbv [zden nth cells_size csize]; lia ] end
              | kx_know1 segs zv xs m ]
      end
  | |- _ => kx_know1 segs zv xs m
  end.


Definition kx_pendingFm (segs : list Segment) (RNG : footprint) (Q : machine_state -> Prop) (F : bvmap 5 word) (fc : bv 32)
  (m rom : word -> option byte) (pc : Z) (stops : list Z) (fuel : nat) (xl : list word) (zv : list Z)
  (zs : list zexp) (zks : list zk) (zrs zws zus : list zreg) : Prop :=
  evtF segs RNG Q (MS (mkRl xl) F (Z_to_bv 64 pc) fc None m rom).

