Tactic Notation "kx_runFm" uconstr(STOPS) uconstr(FUEL) uconstr(KZS) uconstr(RRS) uconstr(WWS) uconstr(UWS) :=
  let S := constr:(STOPS : list Z) in let Fu := constr:(FUEL : nat) in
  let D := eval vm_compute in (repeat false 4096) in
  let K := constr:(KZS : list kz) in let R := constr:(RRS : list (Z * Z)) in let W := constr:(WWS : list (Z * Z)) in
  let U := constr:(UWS : list (Z * Z)) in
  kx_prepFm S Fu K R W U; kx_goFm D.

(* [comment removed for export] *)
Tactic Notation "kx_runFmd" uconstr(STOPS) uconstr(FUEL) uconstr(DIRS) uconstr(KZS) uconstr(RRS) uconstr(WWS) uconstr(UWS) :=
  let S := constr:(STOPS : list Z) in let Fu := constr:(FUEL : nat) in let D := constr:(DIRS : list bool) in
  let K := constr:(KZS : list kz) in let R := constr:(RRS : list (Z * Z)) in let W := constr:(WWS : list (Z * Z)) in
  let U := constr:(UWS : list (Z * Z)) in
  kx_prepFm S Fu K R W U; kx_goFm D.

