Definition rv_chk (na : nat) (reads : list (saddr * nat * bool)) (lr : list (saddr * nat * bool * nat)) : bool :=
  forallb (fun r => let '(a, n, sx, i) := r in
             Nat.leb na i && match nth_error reads (i - na) with
                             | Some (a', n', sx') => saddr_eqb a a' && Nat.eqb n n' && Bool.eqb sx sx'
                             | None => false
                             end) lr.

