Ltac kx_goFL DIRS :=
  lazymatch goal with
  | |- kx_pendingFm ?segs ?RNG ?Q ?F ?fc ?m ?rom ?pc ?stops ?fuel ?xl ?zv ?zs ?zks ?zrs ?zws ?zus =>
    let na := eval vm_compute in (length zv) in
    let sr := constr:(ELit 0 :: map (fun z => lnorm (zx z)) zs) in
    let kn0 := constr:(map zk_ent zks) in
    (* [comment removed for export] *)
    let ispec := eval vm_compute in (find_idx zks) in
    let scs0 := lazymatch ispec with
                | Some _ =>
                    let r0 := eval vm_compute in
                      (kxl_exec segs (tabs_of zks) (shz_of zks) fuel stops (SCR DIRS [] []) (SS pc sr [] (kn0 ++ atom_ranges na) na)) in
                    lazymatch r0 with (?ss0, ?scs0, ?scr0, ?accs0, ?lk0, ?lr0) => scs0 end
                | None => constr:(@nil sidecond)
                end in
    let ifs := lazymatch ispec with
               | Some (?ztl, ?zT) =>
                   let s0 := eval vm_compute in (zle (ZSub (ZL 64) ztl)) in
                   let Tx := eval vm_compute in (zle zT) in
                   eval vm_compute in (idx_facts Tx s0 scs0)
               | None => constr:(@nil kentry)
               end in
    let kn := constr:((kn0 ++ atom_ranges na) ++ ifs) in
    let rr := constr:(map zr_reg zrs) in
    let ww := constr:(map zr_reg zws) in
    let uw := constr:(map zr_reg zus) in
    (* [comment removed for export] *)
    let HK0 := fresh "HK0" in let HTB0 := fresh "HTB0" in let HSH0 := fresh "HSH0" in let HRR0 := fresh "HRR0" in
    let HWW0 := fresh "HWW0" in let HUW0 := fresh "HUW0" in let HUR0 := fresh "HUR0" in let HSR0 := fresh "HSR0" in
    let KXR0 := fresh "KXR0" in
    (* [comment removed for export] *)
    (assert (HK0 : forall xs, know_ok segs (kE zv xs) m kn);
     [ let xs := fresh "xs" in intros xs; unfold know_ok; apply Forall_app; split;
       [ apply Forall_app; split; [ | apply atom_ranges_ok];
         apply Forall_map_iff; kx_forall; kx_know1m segs zv xs m
       | lazymatch ispec with
         | Some (?ztl, ?zT) =>
             let s0 := eval vm_compute in (zle (ZSub (ZL 64) ztl)) in
             let Tx := eval vm_compute in (zle zT) in
             let tlz := eval cbv [zden nth] in (zden zv ztl) in
             let IEQ := fresh "IEQ" in
             assert (IEQ : idx_facts Tx s0 scs0 = ifs) by (vm_compute; reflexivity);
             rewrite <- IEQ; clear IEQ;
             apply (idx_facts_ok segs (kE zv xs) m Tx s0 tlz scs0);
             [ exact (zle_ok zv xs zT (eq_refl true)) | exact (zle_ok zv xs (ZSub (ZL 64) ztl) (eq_refl true)) | lia ]
         | None => constructor
         end ] | ]);
    [> idtac .. |
    assert (HSH0 : forall xs, Forall (shz_ok m (kE zv xs)) (shz_of zks))
      by (let xs := fresh "xs" in intros xs; cbn [shz_of]; kx_forall; kx_shz1 segs zv xs m);
    assert (HTB0 : forall xs, Forall (tab_ok segs m (kE zv xs)) (tabs_of zks))
      by (let xs := fresh "xs" in intros xs; cbn [tabs_of]; kx_forall; kx_tab1 segs zv xs m);
    assert (HRR0 : forall xs, Forall (region_ok segs m (kE zv xs)) rr)
      by (let xs := fresh "xs" in intros xs; apply Forall_map_iff; kx_forall; kx_region1 segs zv xs m);
    assert (HWW0 : forall xs, Forall (win_ok RNG (kE zv xs)) ww)
      by (let xs := fresh "xs" in intros xs; apply Forall_map_iff; kx_forall; kx_win1 segs RNG zv xs);
    assert (HUW0 : forall xs, Forall (unp_ok m (kE zv xs)) uw)
      by (let xs := fresh "xs" in intros xs; apply Forall_map_iff; kx_forall; kx_unp1 zv xs m);
    assert (HUR0 : forall xs, Forall (unp_racc RNG (kE zv xs)) uw)
      by (let xs := fresh "xs" in intros xs; apply Forall_map_iff; kx_forall; kx_unpr1 RNG zv xs);
    assert (HSR0 : forall xs, Forall (shz_racc RNG (kE zv xs)) (shz_of zks))
      by (let xs := fresh "xs" in intros xs; cbn [shz_of]; kx_forall; kx_shr1 RNG zv xs);
    assert (KXR0 : forall xs, regs_ok (kE zv xs) sr (mkRl xl))
      by (let xs := fresh "xs" in intros xs; kx_regs_ok zv);
    let r := eval vm_compute in (kxl_exec segs (tabs_of zks) (shz_of zks) fuel stops (SCR DIRS [] []) (SS pc sr [] kn na)) in
    lazymatch r with (?ss', ?scs, ?scr', ?accs, ?lk, ?lr) =>
      let knF := eval vm_compute in (s_know ss') in
      let reads := eval vm_compute in (kx_reads_of na scs) in
      let ws := constr:(map (Z_to_bv 64) zv) in
      let KXS := fresh "KXxs" in
      pose (KXS := kx_vals segs m ws reads);
      let xs := constr:(KXS) in
      let KXE := fresh "KXE" in
      pose (KXE := kx_env ws xs);
      let E := constr:(KXE) in
      let KXA := fresh "KXA" in
      assert (KXA : forall j, (j < length zv)%nat -> ev KXE j = Z_to_bv 64 (nth j zv 0)) by exact (kE_atom zv KXS);
      let KXRUN := fresh "KXRUN" in
      assert (KXRUN : kxl_exec segs (tabs_of zks) (shz_of zks) fuel stops (SCR DIRS [] []) (SS pc sr [] kn na) = r)
        by (vm_cast_no_check (@eq_refl _ r));
      let HK := fresh "HK" in let HTB := fresh "HTB" in let HSH := fresh "HSH" in let HRV := fresh "HRV" in
      let HKF := fresh "HKF" in let HRR := fresh "HRR" in let HWW := fresh "HWW" in let HUW := fresh "HUW" in
      let HUR := fresh "HUR" in let KXR := fresh "KXR" in
      pose proof (HK0 KXS) as HK; pose proof (HSH0 KXS) as HSH; pose proof (HTB0 KXS) as HTB; pose proof (HRR0 KXS) as HRR;
      pose proof (HWW0 KXS) as HWW; pose proof (HUW0 KXS) as HUW; pose proof (HUR0 KXS) as HUR; pose proof (KXR0 KXS) as KXR;
      change (kE zv KXS) with KXE in HK, HSH, HTB, HRR, HWW, HUW, HUR, KXR;
      assert (HRV : Forall (rv_ok segs m E) lr) by (apply (rv_chk_ok segs m ws reads lr); vm_compute; reflexivity);
      assert (HKF : know_ok segs E m knF)
        by (change knF with (s_know ss');
            exact (kxl_know_final segs (tabs_of zks) (shz_of zks) fuel stops (SCR DIRS [] []) pc sr kn na ss' scs scr' accs lk lr E m
                     KXRUN HK HTB HSH HRV));
      unfold kx_pendingFm;
      refine (kx_run_evtFL segs RNG (tabs_of zks) (shz_of zks) fuel stops (SCR DIRS [] []) pc sr kn na ss' scs scr' accs lk lr
                E (mkRl xl) F fc m rom Q (rfull_mkRl xl) KXRUN KXR HK HTB HSH HRV _ _ _);
      [ apply (kx_scs_bulk3 segs m ws reads knF rr (shz_of zks) uw scs);
          [ vm_compute; reflexivity | exact HKF | exact HRR | exact HSH | exact HUW | ];
        let rest := eval vm_compute in (List.filter (fun s => negb (sc_auto3 na reads knF rr (shz_of zks) uw s)) scs) in
        let REQ := fresh "REQ" in
        assert (REQ : List.filter (fun s => negb (sc_auto3 na reads knF rr (shz_of zks) uw s)) scs = rest) by (vm_compute; reflexivity);
        change (length ws) with na; rewrite REQ; clear REQ; change (scs_denot segs m E rest); unfold scs_denot; kx_forall;
        kx_sc_rest segs m ws reads na
      | let HSR := fresh "HSR" in
        pose proof (HSR0 KXS) as HSR; change (kE zv KXS) with KXE in HSR;
        apply (kx_accs_ok_part3 segs RNG E m m knF ww (shz_of zks) uw accs HKF HWW HSR HUW HUR);
        let rest := eval vm_compute in (List.filter (fun an => negb (acc_auto3 knF ww (shz_of zks) uw an)) accs) in
        let AEQ := fresh "AEQ" in
        assert (AEQ : List.filter (fun an => negb (acc_auto3 knF ww (shz_of zks) uw an)) accs = rest) by (vm_compute; reflexivity);
        rewrite AEQ; clear AEQ HSR; change (Forall (accP RNG E) rest); kx_forall
      | (* [comment removed for export] *)
        clear HRR HWW HSH HUW HUR HTB HRV HK HK0 HSH0 HTB0 HRR0 HWW0 HUW0 HUR0 HSR0 KXR0; rename HKF into HK; intros KXLF;
        cbn [s_log s_regs s_pc] in KXLF |- * ]
    end ]
  end.
(* [comment removed for export] *)
Tactic Notation "kx_runFL" uconstr(STOPS) uconstr(FUEL) uconstr(KZS) uconstr(RRS) uconstr(WWS) uconstr(UWS) :=
  let S := constr:(STOPS : list Z) in let Fu := constr:(FUEL : nat) in
  let D := eval vm_compute in (repeat false 4096) in
  let K := constr:(KZS : list kz) in let R := constr:(RRS : list (Z * Z)) in let W := constr:(WWS : list (Z * Z)) in
  let U := constr:(UWS : list (Z * Z)) in
  kx_prepFm S Fu K R W U; kx_goFL D.
